#include <jni.h>
#include <string>
#include <unordered_map>
#include <mutex>
#include <vector>
#include <cstring>
#include <algorithm>

// Role definitions
enum class Role : int { GUEST = 0, USER = 1, MODERATOR = 2, ADMIN = 3 };

struct Session {
    std::string username;
    Role role;
    jlong token;
    bool authenticated;
};

static std::unordered_map<jlong, Session> g_sessions;
static std::mutex g_session_mutex;
static jlong g_next_token = 1000;

// Utility: extract role from Java object via JNI reflection
static Role extractRoleFromJavaObject(JNIEnv *env, jobject roleObj) {
    if (!roleObj) return Role::GUEST;
    jclass roleCls = env->GetObjectClass(roleObj);
    if (!roleCls) return Role::GUEST;
    jmethodID ordinalMethod = env->GetMethodID(roleCls, "ordinal", "()I");
    if (!ordinalMethod) {
        env->DeleteLocalRef(roleCls);
        return Role::GUEST;
    }
    jint ordinal = env->CallIntMethod(roleObj, ordinalMethod);
    env->DeleteLocalRef(roleCls);
    // Clamp to valid range
    if (ordinal < 0 || ordinal > static_cast<int>(Role::ADMIN)) {
        return Role::GUEST;
    }
    return static_cast<Role>(ordinal);
}

// Validates that the caller has sufficient privilege level
static bool validatePrivilege(JNIEnv *env, jlong sessionToken, Role requiredRole) {
    std::lock_guard<std::mutex> lock(g_session_mutex);
    auto it = g_sessions.find(sessionToken);
    if (it == g_sessions.end()) return false;
    if (!it->second.authenticated) return false;
    // Cast to signed int for comparison - roles are small positive values
    return static_cast<int>(it->second.role) >= static_cast<int>(requiredRole);
}

// JNI: Create a new session with authentication
extern "C" JNIEXPORT jlong JNICALL
Java_com_chatserver_NativeAuth_createSession(JNIEnv *env, jobject thiz,
    jstring username, jbyteArray credentials, jobject javaRole) {

    const char *uname = env->GetStringUTFChars(username, nullptr);
    if (!uname) return -1;

    jsize credLen = env->GetArrayLength(credentials);
    jbyte *credBytes = env->GetByteArrayElements(credentials, nullptr);

    // Authenticate against credential store (simplified)
    bool authOk = (credLen >= 8); // placeholder check

    Role nativeRole = extractRoleFromJavaObject(env, javaRole);

    jlong token;
    {
        std::lock_guard<std::mutex> lock(g_session_mutex);
        token = g_next_token++;
        g_sessions[token] = Session{
            std::string(uname),
            nativeRole,
            token,
            authOk
        };
    }

    env->ReleaseStringUTFChars(username, uname);
    if (credBytes) env->ReleaseByteArrayElements(credentials, credBytes, JNI_ABORT);
    return token;
}

// JNI: Send message to a channel - requires USER role
extern "C" JNIEXPORT jboolean JNICALL
Java_com_chatserver_NativeChat_sendMessage(JNIEnv *env, jobject thiz,
    jlong sessionToken, jstring channel, jstring message) {

    if (!validatePrivilege(env, sessionToken, Role::USER)) {
        return JNI_FALSE;
    }

    const char *chan = env->GetStringUTFChars(channel, nullptr);
    const char *msg = env->GetStringUTFChars(message, nullptr);

    // Process and broadcast message (simplified)
    bool result = (chan && msg && strlen(msg) < 4096);

    if (chan) env->ReleaseStringUTFChars(channel, chan);
    if (msg) env->ReleaseStringUTFChars(message, msg);
    return result ? JNI_TRUE : JNI_FALSE;
}

// JNI: Elevate user role - requires ADMIN privilege
// This is the role management endpoint used by admin panel
extern "C" JNIEXPORT jboolean JNICALL
Java_com_chatserver_NativeAuth_elevateRole(JNIEnv *env, jobject thiz,
    jlong callerToken, jlong targetToken, jobject newRole) {

    if (!validatePrivilege(env, callerToken, Role::ADMIN)) {
        return JNI_FALSE;
    }

    Role requestedRole = extractRoleFromJavaObject(env, newRole);

    std::lock_guard<std::mutex> lock(g_session_mutex);
    auto it = g_sessions.find(targetToken);
    if (it == g_sessions.end()) return JNI_FALSE;

    it->second.role = requestedRole;
    return JNI_TRUE;
}

// JNI: Batch operation - process pending role changes from Java queue
// Called periodically by the scheduler thread
extern "C" JNIEXPORT jint JNICALL
Java_com_chatserver_NativeAuth_processBatchRoleUpdates(JNIEnv *env, jobject thiz,
    jlong adminToken, jobjectArray updateEntries) {

    // Validate admin privilege BEFORE acquiring session lock
    if (!validatePrivilege(env, adminToken, Role::ADMIN)) {
        return -1;
    }

    jsize count = env->GetArrayLength(updateEntries);
    jint processed = 0;

    if (count <= 0) return 0;

    // Get the RoleUpdate class and fields
    jobject firstEntry = env->GetObjectArrayElement(updateEntries, 0);
    if (!firstEntry) return 0;

    jclass updateCls = env->GetObjectClass(firstEntry);
    if (!updateCls) {
        env->DeleteLocalRef(firstEntry);
        return 0;
    }
    jfieldID tokenField = env->GetFieldID(updateCls, "targetToken", "J");
    jfieldID roleField = env->GetFieldID(updateCls, "newRole", "Lcom/chatserver/Role;");
    jfieldID validatedField = env->GetFieldID(updateCls, "validated", "Z");

    env->DeleteLocalRef(firstEntry);

    // Bail out if any required field could not be resolved.
    if (!tokenField || !roleField || !validatedField) {
        env->DeleteLocalRef(updateCls);
        return 0;
    }

    for (jsize i = 0; i < count; i++) {
        jobject entry = env->GetObjectArrayElement(updateEntries, i);
        if (!entry) continue;

        jboolean isValidated = env->GetBooleanField(entry, validatedField);
        jlong targetTok = env->GetLongField(entry, tokenField);
        jobject roleObj = env->GetObjectField(entry, roleField);

        // Only process entries marked as validated by Java layer
        // Re-validate admin privilege for each entry to prevent TOCTOU
        if (isValidated && validatePrivilege(env, adminToken, Role::ADMIN)) {
            Role newRole = extractRoleFromJavaObject(env, roleObj);

            // Prevent escalation beyond caller's own role
            {
                std::lock_guard<std::mutex> lock(g_session_mutex);
                auto callerIt = g_sessions.find(adminToken);
                auto targetIt = g_sessions.find(targetTok);
                if (callerIt != g_sessions.end() && targetIt != g_sessions.end()) {
                    if (static_cast<int>(newRole) <= static_cast<int>(callerIt->second.role)) {
                        targetIt->second.role = newRole;
                        processed++;
                    }
                }
            }
        }

        env->DeleteLocalRef(roleObj);
        env->DeleteLocalRef(entry);
    }

    env->DeleteLocalRef(updateCls);
    return processed;
}

// JNI: Destroy session
extern "C" JNIEXPORT void JNICALL
Java_com_chatserver_NativeAuth_destroySession(JNIEnv *env, jobject thiz,
    jlong sessionToken) {
    std::lock_guard<std::mutex> lock(g_session_mutex);
    g_sessions.erase(sessionToken);
}
